/* Sidebar Mercantil (Custom Widget) — replica Sidebar.tsx/Sidebar.svelte:
 * ítems fijos de navegación, badge de contador en "Bandeja de tareas",
 * navegación vía appsmith.triggerEvent('onNavigate', {pageName}) — el mismo
 * mecanismo que ya usa navMenu.json en el proyecto APAP de referencia. */

const ITEMS = [
  { label: "Bandeja de tareas", pageName: "BandejaTareas", badgeKey: "pendingTaskCount" },
  { label: "Procesos", pageName: "Procesos" },
  { label: "Casos", pageName: "Casos" },
  { label: "Monitorización", pageName: "Monitorizacion" }
];

appsmith.onReady(() => {
  render(appsmith.model);
  if (typeof appsmith.onModelChange === "function") {
    appsmith.onModelChange((m) => render(m));
  }
});

function render(model) {
  const nav = document.getElementById("mc-nav");
  if (!nav) return;
  nav.innerHTML = "";

  const activePage = model && model.activePage;
  const pendingTaskCount = (model && model.pendingTaskCount) || 0;

  ITEMS.forEach((item) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "mc-nav-item" + (item.pageName === activePage ? " active" : "");

    const label = document.createElement("span");
    label.className = "mc-nav-item__label";
    label.textContent = item.label;
    btn.appendChild(label);

    if (item.badgeKey && pendingTaskCount > 0) {
      const badge = document.createElement("span");
      badge.className = "mc-nav-item__badge";
      badge.textContent = String(pendingTaskCount);
      btn.appendChild(badge);
    }

    btn.addEventListener("click", () => {
      appsmith.triggerEvent("onNavigate", { pageName: item.pageName });
    });

    nav.appendChild(btn);
  });
}

document.getElementById("mc-logout") && document.getElementById("mc-logout").addEventListener("click", () => {
  appsmith.triggerEvent("onLogout", {});
});

