.bandeja__list { display: flex; flex-direction: column; gap: 12px; }

.bandeja__empty { color: #4A5568; font-size: 12px; padding: 32px 0; text-align: center; }

.tarea-card {
  display: flex;
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 14px;
  box-shadow: rgba(0,0,0,.1) 0px 1px 3px, rgba(0,0,0,.06) 0px 1px 2px;
  overflow: hidden;
}

.tarea-card__body { flex: 1; padding: 16px 18px; min-width: 0; }

.tarea-card__tags { display: flex; align-items: center; gap: 8px; margin-bottom: 7px; flex-wrap: wrap; }

.tarea-card__tag {
  font-weight: 700;
  font-size: 8.5px;
  letter-spacing: .5px;
  color: #14327D;
  background: rgba(30,95,168,.1);
  padding: 3px 8px;
  border-radius: 999px;
  white-space: nowrap;
}

.tarea-card__name { font-weight: 600; font-size: 14.5px; color: #1D2751; }

.tarea-card__caso { font-size: 10.5px; color: #9CA3AF; margin-top: 2px; }

.tarea-card__side {
  width: 190px;
  flex-shrink: 0;
  border-left: 1px solid #E5E7EB;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-end;
  gap: 12px;
}

.tarea-card__prioridad {
  font-size: 9.5px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
  background: #E8F0FE;
  color: #2557A7;
}
.tarea-card__prioridad--alta { background: #FCECEC; color: #D6202A; }

.tarea-card__btn {
  background: linear-gradient(90deg, #1E5FA8 0%, #2E7BD6 100%);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 8px 18px;
  font-family: inherit;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
}
.tarea-card__btn:disabled { opacity: .4; cursor: not-allowed; }

.tarea-card__btn--ghost {
  background: #fff;
  color: #14327D;
  border: 1.5px solid #6FA3DC;
}

