/* Bandeja de tareas (Custom Widget). model = { tareas: [...], userId } que
 * el layout de la página arma con bandejaLogica.tareasUnicas() +
 * bandejaLogica.esMia(t) + GetSesion.data.user_id. Las acciones Tomar/
 * Liberar/Abrir se disparan como eventos hacia el editor (igual que el
 * sidebar), donde bandejaLogica.tomar/liberar ya invocan las queries reales. */

function tipoTag(nombre) {
  if (!nombre) return "TAREA";
  const n = nombre.toLowerCase();
  if (n.includes("vip") || n.includes("excepci")) return "REVISIÓN VIP";
  if (n.includes("gesti") && n.includes("manual")) return "GESTIÓN MANUAL";
  if (n.includes("solicitud") && n.includes("producto")) return "SOLICITUD DE PRODUCTO";
  if (n.includes("solicitud") && n.includes("informaci")) return "SOLICITUD DE INFORMACIÓN";
  return "TAREA";
}

appsmith.onReady(() => {
  render(appsmith.model);
  if (typeof appsmith.onModelChange === "function") {
    appsmith.onModelChange((m) => render(m));
  }
});

function render(model) {
  const tareas = (model && model.tareas) || [];
  const userId = model && model.userId ? String(model.userId) : null;

  const total = tareas.length;
  const alta = tareas.filter((t) => t.priority === "high" || t.priority === "highest").length;

  const kpiTotal = document.getElementById("kpi-total");
  const kpiAlta = document.getElementById("kpi-alta");
  if (kpiTotal) kpiTotal.textContent = String(total);
  if (kpiAlta) kpiAlta.textContent = String(alta);

  const list = document.getElementById("bandeja-list");
  const empty = document.getElementById("bandeja-empty");
  if (!list || !empty) return;

  list.innerHTML = "";

  if (tareas.length === 0) {
    empty.style.display = "block";
    return;
  }
  empty.style.display = "none";

  tareas.forEach((t) => {
    const mia = userId && String(t.assigned_id) === userId;

    const card = document.createElement("div");
    card.className = "tarea-card";

    const body = document.createElement("div");
    body.className = "tarea-card__body";

    const tags = document.createElement("div");
    tags.className = "tarea-card__tags";
    const tag = document.createElement("span");
    tag.className = "tarea-card__tag";
    tag.textContent = tipoTag(t.displayName);
    tags.appendChild(tag);
    body.appendChild(tags);

    const name = document.createElement("div");
    name.className = "tarea-card__name";
    name.textContent = t.displayName || "Tarea pendiente";
    body.appendChild(name);

    const caso = document.createElement("div");
    caso.className = "tarea-card__caso";
    caso.textContent = "Caso #" + t.caseId;
    body.appendChild(caso);

    card.appendChild(body);

    const side = document.createElement("div");
    side.className = "tarea-card__side";

    const prioridad = document.createElement("span");
    const esAlta = t.priority === "high" || t.priority === "highest";
    prioridad.className = "tarea-card__prioridad" + (esAlta ? " tarea-card__prioridad--alta" : "");
    prioridad.textContent = esAlta ? "Alta" : "Normal";
    side.appendChild(prioridad);

    if (mia) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "tarea-card__btn";
      btn.textContent = "Abrir tarea";
      btn.addEventListener("click", () => {
        appsmith.triggerEvent("onAbrirTarea", { taskId: t.id, displayName: t.displayName });
      });
      side.appendChild(btn);

      const btnLiberar = document.createElement("button");
      btnLiberar.type = "button";
      btnLiberar.className = "tarea-card__btn tarea-card__btn--ghost";
      btnLiberar.textContent = "Liberar";
      btnLiberar.style.marginTop = "6px";
      btnLiberar.addEventListener("click", () => {
        appsmith.triggerEvent("onLiberar", { taskId: t.id });
      });
      side.appendChild(btnLiberar);
    } else {
      const btnTomar = document.createElement("button");
      btnTomar.type = "button";
      btnTomar.className = "tarea-card__btn tarea-card__btn--ghost";
      btnTomar.textContent = "Tomar";
      btnTomar.addEventListener("click", () => {
        appsmith.triggerEvent("onTomar", { taskId: t.id });
      });
      side.appendChild(btnTomar);
    }

    card.appendChild(side);
    list.appendChild(card);
  });
}

